// La pasarela llama aquí cuando un pago cambia de estado
app.post('/webhooks/pagos', verificarFirma, async (req, res) => {
  const { evento, pedidoId } = req.body;
  if (evento === 'pago.aprobado') {
    await pedidos.marcarPagado(pedidoId);
  }
  res.sendStatus(200); // confirma la recepción
});

